(async()=>{const out={},grab=(x,x0=0,w=2)=>{const d=x.getImageData(x0,0,w,1,{pixelFormat:'rgba-float16'});return {space:d.colorSpace,format:d.pixelFormat,type:d.data.constructor.name,data:[...d.data]}};
for(const space of ['srgb','display-p3']){const c=new OffscreenCanvas(3,1),x=c.getContext('2d',{colorSpace:space,colorType:'float16',willReadFrequently:true}),pixels=new Float16Array([1.5,.25,-.5,1,.5,1,.25,.5]);const d=new ImageData(pixels,2,1,{colorSpace:space,pixelFormat:'rgba-float16'});x.putImageData(d,0,0);const row={alias:d.data===pixels,read:grab(x),overlap:grab(x,1,1)};const bitmap=await createImageBitmap(c),other=new OffscreenCanvas(3,1),y=other.getContext('2d',{colorSpace:space,colorType:'float16',willReadFrequently:true});y.drawImage(bitmap,0,0);row.copy=grab(y);y.clearRect(0,0,3,1);y.drawImage(c,0,0);row.direct=grab(y);const raw=await createImageBitmap(c,{colorSpaceConversion:'none'});y.clearRect(0,0,3,1);y.drawImage(raw,0,0);row.noConversion=grab(y);raw.close();bitmap.close();row.closed=[bitmap.width,bitmap.height];x.clearRect(0,0,1,1);row.local=grab(x);row.copyStable=grab(y);c.width=3;row.reset=grab(x);row.attributes=x.getContextAttributes();out[space]=row;}
const errors={};for(const [key,fn]of Object.entries({badSpace:()=>new ImageData(1,1,{colorSpace:'x'}),badFormat:()=>new ImageData(1,1,{pixelFormat:'x'}),mismatched:()=>new ImageData(new Uint8ClampedArray(4),1,1,{pixelFormat:'rgba-float16'}),zero:()=>new ImageData(new Float16Array(0),1)})){try{fn();errors[key]='success'}catch(e){errors[key]=e.name}}out.errors=errors;return out})()